-- Всички населени места в България (5267 града и села), по официалния
-- ЕКАТТЕ регистър на НСИ: име, община, област, вид (град/село) и ЕКАТТЕ код.
-- Използвани са САМО административните факти от официалния регистър — без
-- геокоординати (те и без това не ни трябват: селата нарочно не се показват
-- като точки на картата, само в списъка/търсачката, виж 0024).
--
-- Новите колони:
--   municipality — община (нужна за разграничаване на съименници; 527 имена
--                  се срещат повече от веднъж в страната, напр. две различни
--                  "Банкя" — в Столична община и в община Трън)
--   is_village   — true за село, false за град (за префикса "гр."/"с." в UI)
--   ekatte       — официалният код, уникален ключ за идемпотентност на тази
--                  и бъдещи миграции
--
-- Съществуващите редове (seed-натите в 0002/0014/0024) се запазват заедно с
-- координатите си — само им се попълват новите колони по съвпадение на
-- име+област, когато е еднозначно.

alter table public.cities
  add column if not exists municipality text,
  add column if not exists is_village boolean not null default false,
  add column if not exists ekatte text;

-- Три имена от 0024 не съществуват в официалния регистър (писани по памет):
--   "Боженци"        -> официално е "Боженците" (общ. Габрово)
--   "Долни Пасарел"  -> в Столична община (София-град), не в София (област)
--   "Русалка"        -> курортен комплекс, не самостоятелно населено място
update public.cities set name = 'Боженците'
  where name = 'Боженци' and region = 'Габрово';
update public.cities set region = 'София-град'
  where name = 'Долни Пасарел' and region = 'София (област)';
delete from public.cities c
  where c.name = 'Русалка' and c.region = 'Добрич'
    and not exists (select 1 from public.listings l where l.city_id = c.id);

create table if not exists public._ekatte_import (
  name text not null,
  region text not null,
  municipality text not null,
  is_village boolean not null,
  ekatte text not null
);

