-- Попълва новите колони на вече съществуващите редове (пази им lat/lng).
-- Само при еднозначно съвпадение име+област — иначе не е ясно кой ред кой е.
update public.cities c
set municipality = e.municipality,
    is_village = e.is_village,
    ekatte = e.ekatte
from public._ekatte_import e
where c.ekatte is null
  and c.name = e.name
  and c.region = e.region
  and (
    select count(*) from public._ekatte_import e2
    where e2.name = c.name and e2.region = c.region
  ) = 1;

-- Втора стъпка за трите seed-нати общински центъра, в чиято област има и
-- едноименно СЕЛО (Костенец, Каспичан, Елин Пелин) — seed-натият ред винаги
-- е градът, така че се връзва с градската версия. Без тази стъпка редът
-- оставаше несвързан и градът щеше да се появи два пъти в списъка.
update public.cities c
set municipality = e.municipality,
    is_village = e.is_village,
    ekatte = e.ekatte
from public._ekatte_import e
where c.ekatte is null
  and c.name = e.name
  and c.region = e.region
  and e.is_village = false
  and (
    select count(*) from public._ekatte_import e2
    where e2.name = c.name and e2.region = c.region and e2.is_village = false
  ) = 1;

-- Всичко останало от регистъра влиза като нов ред, без координати.
insert into public.cities (name, region, municipality, is_village, ekatte)
select e.name, e.region, e.municipality, e.is_village, e.ekatte
from public._ekatte_import e
where not exists (
  select 1 from public.cities c where c.ekatte = e.ekatte
);

drop table public._ekatte_import;

-- Уникалност по официален код (само за редовете, които имат такъв — старите
-- ръчни seed-ове без съвпадение в регистъра остават с ekatte = null).
create unique index if not exists cities_ekatte_key
  on public.cities (ekatte) where ekatte is not null;

-- Индекс за търсачката с автодовършване (prefix търсене, ilike 'ва%').
create index if not exists cities_name_prefix_idx
  on public.cities (lower(name) text_pattern_ops);
